package com.bank.normalizer;

import java.util.*;
import java.util.logging.*;

public class UnaryOperatorDemo {
    private static final Logger log = Logger.getLogger("Normalizer");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<String> names = new ArrayList<>(List.of("  Rajesh ", "PRIYA", " Amit"));
        NameNormalizer normalizer = new NameNormalizer();

        normalizer.normalizeAll(names);              // in place
        log.info(() -> "normalized: " + names);
        log.info(() -> "single    : " + normalizer.normalize("  Vikram  "));
    }
}

// ─── Would be in service/NameNormalizer.java ───
class NameNormalizer {
    // same type in and out → UnaryOperator<String>
    private final java.util.function.UnaryOperator<String> normalize =
        s -> s.strip().toLowerCase();   // strip() is Unicode-aware (Java 11+)

    String normalize(String s) { return normalize.apply(s); }

    void normalizeAll(List<String> names) {
        names.replaceAll(normalize);    // replaceAll takes a UnaryOperator
    }
}
